            LazyColumn(modifier = Modifier.fillMaxWidth().heightIn(max = 360.dp)) {
                profiles.forEach { profile ->
                    item(key = profile.id) {
                        Row(
                            modifier = Modifier.fillMaxWidth()
                                .clip(RoundedCornerShape(6.dp))
                                .clickable { onSelected(profile) }
